        });
        const [result] = await service.gatherInvoiceLines({
            businessID: 'biz',
            catalogueBucket: 'bucket',
            catalogueKey: 'key',
        });
        return result.lineItems;
    };

    test('plain metered dimension with no allowance charges all usage', async () => {
        const lines = await run(FreeDimensionOnInvoice.show, [dimension({ dimensionId: 'a', dimensionName: 'A', consumptionPrice: '0.01' })], { a: 100 });
        expect(lines).toEqual([{ name: 'A - Plan', quantity: 100, unitCost: 0.01 }]);
    });

    test('finite exhausted allowance with overage permitted charges only the overage', async () => {
        const lines = await run(FreeDimensionOnInvoice.show, [dimension({ dimensionId: 'a', dimensionName: 'A', consumptionPrice: '10', usageEntitlement: 10, overageAllowed: 'true' })], { a: 12 });
        expect(lines).toEqual([{ name: 'A - Plan', quantity: 2, unitCost: 10 }]);
    });

    test('unexhausted allowance charges nothing', async () => {
        const lines = await run(FreeDimensionOnInvoice.show, [dimension({ dimensionId: 'a', dimensionName: 'A', consumptionPrice: '0.02', usageEntitlement: 100, overageAllowed: 'true' })], { a: 80 });
        expect(lines).toEqual([]);
    });

    test('unlimited allowance charges nothing', async () => {
        const lines = await run(FreeDimensionOnInvoice.show, [dimension({ dimensionId: 'a', dimensionName: 'A', consumptionPrice: '0.2', usageEntitlement: 'inf', overageAllowed: 'true' })], { a: 40 });
        expect(lines).toEqual([]);
    });

    test('plan that forbids overage charges nothing beyond the allowance', async () => {
        const lines = await run(FreeDimensionOnInvoice.show, [dimension({ dimensionId: 'a', dimensionName: 'A', consumptionPrice: '1', usageEntitlement: 5, overageAllowed: 'false' })], { a: 7 });
        expect(lines).toEqual([]);
    });

    test('allowance with overage neither true charges nothing', async () => {
        const lines = await run(FreeDimensionOnInvoice.show, [dimension({ dimensionId: 'a', dimensionName: 'A', consumptionPrice: '0.1', usageEntitlement: 50 })], { a: 70 });
        expect(lines).toEqual([]);
    });

    test('zero priced dimension shows when free dimensions are shown', async () => {
        const lines = await run(FreeDimensionOnInvoice.show, [dimension({ dimensionId: 'a', dimensionName: 'A', consumptionPrice: '0.00' })], { a: 10 });
        expect(lines).toEqual([{ name: 'A - Plan', quantity: 10, unitCost: 0 }]);
    });

    test('zero priced dimension is hidden when free dimensions are hidden', async () => {
        const lines = await run(FreeDimensionOnInvoice.hide, [dimension({ dimensionId: 'a', dimensionName: 'A', consumptionPrice: '0.00' })], { a: 10 });
        expect(lines).toEqual([]);
    });
});
